<?php
$goalMap=[];
foreach($goals as $g){
    $goalMap[(string)$g['account_id']]=[
        'daily_goal'=>(float)$g['daily_goal'],
        'weekly_goal'=>(float)$g['weekly_goal'],
        'monthly_goal'=>(float)$g['monthly_goal'],
        'yearly_goal'=>(float)$g['yearly_goal']
    ];
}
?>
<div class="page-title">P&amp;L Goals</div><p class="page-subtitle">Set target net P&amp;L for each account across daily, weekly, monthly and yearly periods.</p>
<div class="card form-card"><div class="section-heading"><div><h2>Set goals</h2><div class="sub">Select an account to load its existing goals, change them, and save.</div></div></div><form method="post" action="/goals" id="goals-form"><?=csrf_field()?><div class="grid"><p><label>Account</label><select name="account_id" id="goal-account" required><option value="">Select account...</option><?php foreach($accounts as $a):?><option value="<?=$a['id']?>"><?=e($a['name'].' ('.$a['currency'].')')?></option><?php endforeach;?></select></p><p><label>Daily P&amp;L goal</label><input id="daily-goal" type="number" step="0.01" min="0" name="daily_goal" value="0" required></p><p><label>Weekly P&amp;L goal</label><input id="weekly-goal" type="number" step="0.01" min="0" name="weekly_goal" value="0" required></p><p><label>Monthly P&amp;L goal</label><input id="monthly-goal" type="number" step="0.01" min="0" name="monthly_goal" value="0" required></p><p><label>Yearly P&amp;L goal</label><input id="yearly-goal" type="number" step="0.01" min="0" name="yearly_goal" value="0" required></p></div><div class="actions"><button>Save goals</button></div></form></div>
<div class="card table-wrap"><div class="section-heading"><div><h2>Current goals</h2><div class="sub">One goal profile per account.</div></div></div><table><thead><tr><th>Account</th><th>Daily</th><th>Weekly</th><th>Monthly</th><th>Yearly</th><th>Action</th></tr></thead><tbody><?php foreach($goals as $g):?><tr><td><?=e($g['account_name'])?> <span class="muted"><?=e($g['currency'])?></span></td><td><?=number_format((float)$g['daily_goal'],2)?></td><td><?=number_format((float)$g['weekly_goal'],2)?></td><td><?=number_format((float)$g['monthly_goal'],2)?></td><td><?=number_format((float)$g['yearly_goal'],2)?></td><td><button type="button" class="secondary goal-edit" data-account="<?=$g['account_id']?>">Edit</button></td></tr><?php endforeach;?><?php if(!$goals):?><tr><td colspan="6" class="muted">No P&amp;L goals configured yet.</td></tr><?php endif;?></tbody></table></div>
<script nonce="<?=e(csp_nonce())?>">(function(){const goals=<?=json_encode($goalMap,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;const account=document.getElementById('goal-account');const set=(id,v)=>{const el=document.getElementById(id);if(el)el.value=v??0};function load(){const g=goals[account.value]||{daily_goal:0,weekly_goal:0,monthly_goal:0,yearly_goal:0};set('daily-goal',g.daily_goal);set('weekly-goal',g.weekly_goal);set('monthly-goal',g.monthly_goal);set('yearly-goal',g.yearly_goal)}account.addEventListener('change',load);document.querySelectorAll('.goal-edit').forEach(b=>b.addEventListener('click',()=>{account.value=b.dataset.account;load();document.getElementById('goals-form').scrollIntoView({behavior:'smooth',block:'start'});}));})();</script>
